"""Plot the FG20 diagnostics generated by make -C test uvb-data."""

import argparse
from pathlib import Path

import matplotlib

if __name__ == "__main__":
    matplotlib.use("Agg")

import matplotlib.pyplot as plt
import numpy as np

from plot_style import BLACK, BLUE, GRAY, ORANGE, PLOT_STYLE, PURPLE


PLOT_DIR = Path(__file__).resolve().parent
REDSHIFTS = (0, 1, 2, 3)
REDSHIFT_COLORS = (BLACK, BLUE, ORANGE, PURPLE)
DISK_REDSHIFTS = (0, 2)
COLUMN_LABEL = r"Shielding column per face [cm$^{-2}$]"
DENSITY_LABEL = r"Hydrogen nucleus density [cm$^{-3}$]"


def load_results(data_dir):
    data = {
        key: np.genfromtxt(data_dir / name, names=True, delimiter=",", dtype=None, encoding="utf-8", ndmin=1)
        for key, name in (
            ("equilibrium", "equilibrium.csv"), ("secondary", "secondary.csv"),
            ("disk_grid", "disk-grid.csv"), ("disk_history", "disk-history.csv"),
            ("cooling_curve", "cooling-curve.csv"),
        )
    }
    data["shielding"] = np.loadtxt(
        data_dir / "UVBackgroundRates.dat", usecols=(0, 1, 2, 3, 4), ndmin=1,
        dtype=[("z", float), ("column", float), ("ion", "U4"), ("gamma", float),
               ("power", float)],
    )
    if not all(len(rows) for rows in data.values()):
        raise ValueError(f"Empty UVB diagnostic in {data_dir}")
    if np.any(data["disk_grid"]["status"] != 0):
        raise ValueError("disk-grid.csv contains unsuccessful updates")
    return data


def plot_shielding(data):
    fig, axes = plt.subplots(2, 2, figsize=(9.6, 6.3), sharex=True, sharey=True, layout="constrained")
    fig.suptitle(r"FG20 self-shielding in a slab · $Z=0$")
    panels = (("HI", "gamma", "H I ionization"), ("HI", "power", "H I photoelectron power"),
              ("HeI", "gamma", "He I ionization"), ("HeII", "gamma", "He II ionization"))
    for ax, (ion, quantity, title) in zip(axes.flat, panels):
        for z, color in zip(REDSHIFTS, REDSHIFT_COLORS):
            rows = np.sort(data[(data["ion"] == ion) & (data["z"] == z)], order="column")
            if not len(rows) or rows["column"][0] != 0 or rows[quantity][0] <= 0:
                raise ValueError(f"Missing unshielded {ion} rate at z={z} in UVBackgroundRates.dat")
            filtered = rows[rows["column"] >= 1e15]
            ax.loglog(filtered["column"], np.ma.masked_less_equal(filtered[quantity] / rows[quantity][0], 0),
                      color=color, label=rf"$z={z}$")
        ax.set_title(title)
    axes[0, 0].set(xlim=(1e15, 1e24), ylim=(None, 1.6))
    for ax in axes[-1]:
        ax.set_xlabel(COLUMN_LABEL)
    for ax in axes[:, 0]:
        ax.set_ylabel("Fraction of the unshielded rate")
    axes[0, 0].legend(ncol=2, loc="lower left")
    return fig


def plot_equilibrium(data):
    fig, axes = plt.subplots(1, 3, figsize=(10, 3.6), sharex=True, layout="constrained")
    fig.suptitle(r"Optically thin H and He · $T=10^4$ K")
    for ax, (stage, label) in zip(axes, (("xHII", "H II"), ("xHeII", "He II"), ("xHeIII", "He III"))):
        for z, color in zip(REDSHIFTS, REDSHIFT_COLORS):
            rows = np.sort(data[data["z"] == z], order="nH")
            ax.loglog(rows["nH"], rows[stage], color=color, label=rf"$z={z}$")
            ax.plot(rows["nH"], rows[stage + "_reference"], "o", color=color, mfc="none", ms=4)
        ax.set(title=label, xlabel=DENSITY_LABEL)
    axes[0].set_ylabel("Ion fraction")
    axes[0].legend(ncol=2, loc="lower left")
    return fig


def plot_secondaries(data):
    fig, (heat, ionize) = plt.subplots(1, 2, figsize=(9.6, 4.0), sharex=True, layout="constrained")
    fig.suptitle(r"Photoelectron deposition · $x_{\mathrm{H,II}}=0.01$, $Z=0$")
    for z, color in zip(DISK_REDSHIFTS, (BLUE, ORANGE)):
        for cutoff, style, label in ((0, "-", "full FG20"), (300, "--", "300 eV cutoff")):
            rows = data[(data["z"] == z) & np.isclose(data["xHII"], 0.01) & (data["energy_max_eV"] == cutoff)]
            rows = np.sort(rows, order="NHI_per_side")
            column = rows["NHI_per_side"]
            heat.semilogx(column, rows["H_UVB"] / rows["P_total"], "o", ls=style, color=color,
                          label=rf"$z={z}$, {label}", ms=4)
            primary = rows["Gamma_HI"] - rows["Gamma2_HI"]
            ionize.loglog(column, rows["Gamma_HI"] / primary, "o", ls=style, color=color, ms=4)
    heat.set(ylabel=r"Heat / photoelectron power", ylim=(0, 1.03))
    ionize.set(ylabel=r"$\Gamma_{\mathrm{H\,I}}^{\rm total}/\Gamma_{\mathrm{H\,I}}^{\rm primary}$")
    for ax in (heat, ionize):
        ax.set_xlabel(COLUMN_LABEL)
    heat.legend(loc="lower left", fontsize=8)
    return fig


def disk_curves(data, redshift, soft_xray, sort_by):
    for mode, style in (("equilibrium", "-"), ("nonequilibrium", "--")):
        for uvb, color in ((0, GRAY), (1, BLUE)):
            rows = data[(data["z"] == redshift) & (data["soft_xray"] == soft_xray)
                        & (data["uvb"] == uvb) & (data["chemistry_mode"] == mode)]
            if not len(rows):
                raise ValueError(f"Missing disk data for z={redshift}, {mode}, UVB={uvb}, soft X-rays={int(soft_xray)}")
            yield np.sort(rows, order=sort_by), color, style, f"UVB {'on' if uvb else 'off'} · {mode}"


def plot_disk_grid(data, soft_xray=False):
    fig, axes = plt.subplots(3, 2, figsize=(9.6, 7.3), sharex="col", sharey="row", layout="constrained")
    xray = "on" if soft_xray else "off"
    fig.suptitle(f"Disk gas after 12 Myr · soft X-rays {xray}")
    for col, z in enumerate(DISK_REDSHIFTS):
        temperature, electrons, heat = axes[:, col]
        for rows, color, style, label in disk_curves(data, z, soft_xray, "nH"):
            density = rows["nH"]
            temperature.loglog(density, rows["T"], ".", ls=style, color=color, label=label)
            electrons.loglog(density, rows["xe"], ".", ls=style, color=color)
            heat.semilogx(density, 100 * rows["H_UVB_over_H_tot"], ".", ls=style, color=color)
        temperature.set_title(rf"$z={z}$")
        heat.set(xlabel=DENSITY_LABEL, ylim=(-3, 105))
    axes[0, 0].set_ylabel("Temperature [K]")
    axes[1, 0].set_ylabel(r"$n_e/n_{\rm H}$")
    axes[2, 0].set_ylabel("UVB share of heating [%]")
    fig.legend(*axes[0, 0].get_legend_handles_labels(), loc="outside lower center", ncol=2)
    return fig


def plot_disk_cooling(data, soft_xray=False):
    if "L_tot" not in data.dtype.names:
        raise ValueError("Regenerate disk-grid.csv with make -C test uvb-data to include L_tot.")
    fig, axes = plt.subplots(2, 2, figsize=(9.6, 5.9), sharex="col", sharey="row", layout="constrained")
    xray = "on" if soft_xray else "off"
    fig.suptitle(f"Disk cooling after 12 Myr · soft X-rays {xray}")
    for col, z in enumerate(DISK_REDSHIFTS):
        cooling, ratio = axes[:, col]
        uvb_off = {}
        for rows, color, style, label in disk_curves(data, z, soft_xray, "nH"):
            density = rows["nH"]
            rate = np.ma.masked_less_equal(rows["L_tot"], 0)
            cooling.loglog(density, rate, ".", ls=style, color=color, label=label)
            mode = rows["chemistry_mode"][0]
            if not rows["uvb"][0]:
                uvb_off[mode] = rows
                continue
            control = uvb_off[mode]
            if not np.array_equal(density, control["nH"]):
                raise ValueError(f"UVB on/off density grids differ at z={z}, {mode}")
            ratio.loglog(density, rate / np.ma.masked_less_equal(control["L_tot"], 0), ".", ls=style, color=color)
        cooling.set_title(rf"$z={z}$")
        ratio.axhline(1, color=GRAY, ls=":", lw=1)
        ratio.set_xlabel(DENSITY_LABEL)
    axes[0, 0].set_ylabel(r"Total cooling [erg cm$^{-3}$ s$^{-1}$]")
    axes[1, 0].set_ylabel(r"$L_{\rm UVB\ on}/L_{\rm UVB\ off}$")
    fig.legend(*axes[0, 0].get_legend_handles_labels(), loc="outside lower center", ncol=2)
    return fig


def plot_cooling_curve(data, soft_xray=False):
    data = data[data["soft_xray"] == soft_xray]
    fixed = ("nH", "N_per_side", "Z")
    if len(np.unique(data[list(fixed)])) != 1:
        raise ValueError("cooling-curve.csv must have one density, shielding column, and metallicity")
    density, column, metallicity = (data[field][0] for field in fixed)
    xray = "on" if soft_xray else "off"
    fig, axes = plt.subplots(2, 2, figsize=(9.6, 5.9), sharex="col", sharey="row", layout="constrained")
    fig.suptitle(
        "Cooling in chemical equilibrium\n"
        rf"$n_{{\rm H}}={density:g}$ cm$^{{-3}}$ · "
        rf"$N_{{\rm shield}}=10^{{{np.log10(column):g}}}$ cm$^{{-2}}$ per face · "
        rf"$Z={metallicity:g}$ · soft X-rays {xray}"
    )
    for col, z in enumerate(DISK_REDSHIFTS):
        cooling, ratio = axes[:, col]
        at_z = data[data["z"] == z]
        off, on = (np.sort(at_z[at_z["uvb"] == uvb], order="T") for uvb in (0, 1))
        if not len(off) or not np.array_equal(off["T"], on["T"]):
            raise ValueError(f"Missing or mismatched UVB on/off temperature grids at z={z}")
        cooling.loglog(off["T"], off["L_tot"], color=GRAY, ls="--", label="UVB off")
        cooling.loglog(on["T"], on["L_tot"], color=BLUE, label="UVB on")
        ratio.loglog(on["T"], on["L_tot"] / off["L_tot"], color=BLUE)
        ratio.axhline(1, color=GRAY, ls=":", lw=1)
        cooling.set_title(rf"$z={z}$")
        ratio.set_xlabel("Temperature [K]")
    axes[0, 0].set_ylabel(r"Total cooling [erg cm$^{-3}$ s$^{-1}$]")
    axes[1, 0].set_ylabel(r"$L_{\rm UVB\ on}/L_{\rm UVB\ off}$")
    fig.legend(*axes[0, 0].get_legend_handles_labels(), loc="outside lower center", ncol=2)
    return fig


def plot_disk_history(data, density=0.01, soft_xray=False):
    selected = data[np.isclose(data["nH"], density, rtol=1e-8, atol=0)]
    if not len(selected):
        raise ValueError(f"Choose nH from {np.unique(data['nH']).tolist()}. No history at {density:g}.")
    fig, axes = plt.subplots(3, 2, figsize=(9.6, 7.3), sharex="col", sharey="row", layout="constrained")
    xray = "on" if soft_xray else "off"
    fig.suptitle(rf"Disk evolution · $n_{{\rm H}}={density:g}$ cm$^{{-3}}$ · soft X-rays {xray}")
    for col, z in enumerate(DISK_REDSHIFTS):
        temperature, ionized, column = axes[:, col]
        for rows, color, style, label in disk_curves(selected, z, soft_xray, "time_Myr"):
            time = rows["time_Myr"]
            temperature.plot(time, rows["T"], ".", ls=style, color=color, label=label)
            ionized.plot(time, rows["xHII"], ".", ls=style, color=color)
            column.semilogy(time, np.ma.masked_less_equal(rows["N_per_side"], 0), ".", ls=style, color=color)
        temperature.set_title(rf"$z={z}$")
        column.set_xlabel("Time [Myr]")
    axes[0, 0].set_ylabel("Temperature [K]")
    axes[1, 0].set_ylabel("H II fraction")
    axes[2, 0].set_ylabel(r"$N_{\rm shield}$ per face [cm$^{-2}$]")
    fig.legend(*axes[0, 0].get_legend_handles_labels(), loc="outside lower center", ncol=2)
    return fig


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--data-dir", type=Path, default=PLOT_DIR.parent / "test" / "out" / "uvb")
    parser.add_argument("--output-dir", type=Path, default=PLOT_DIR / "out" / "uvb")
    parser.add_argument("--history-density", type=float, default=0.01)
    parser.add_argument("--soft-xray", action="store_true", help="Select the disk runs with soft X-rays")
    args = parser.parse_args()
    try:
        data = load_results(args.data_dir)
        with plt.rc_context(PLOT_STYLE):
            figures = {
                "shielding.png": plot_shielding(data["shielding"]),
                "equilibrium.png": plot_equilibrium(data["equilibrium"]),
                "secondaries.png": plot_secondaries(data["secondary"]),
                "disk_grid.png": plot_disk_grid(data["disk_grid"], args.soft_xray),
                "disk_cooling.png": plot_disk_cooling(data["disk_grid"], args.soft_xray),
                "cooling_curve.png": plot_cooling_curve(data["cooling_curve"], args.soft_xray),
                "disk_history.png": plot_disk_history(data["disk_history"], args.history_density, args.soft_xray),
            }
            args.output_dir.mkdir(parents=True, exist_ok=True)
            for name, fig in figures.items():
                fig.savefig(args.output_dir / name, dpi=180)
                plt.close(fig)
    except (OSError, ValueError) as error:
        parser.error(f"{error}. Generate the data with make -C test uvb-data.")
    print(f"UVB plots written to {args.output_dir}")


if __name__ == "__main__":
    main()
